static List<ConsumerRecord<String, String>> readTen(KafkaConsumer<String, String> consumer) {
    TopicPartition tp = new TopicPartition("payments", 0);
    consumer.assign(List.of(tp));
    consumer.seek(tp, 50);
    List<ConsumerRecord<String, String>> out = new ArrayList<>();
    long deadline = System.nanoTime() + Duration.ofSeconds(5).toNanos();
    while (out.size() < 10 && System.nanoTime() < deadline) {
        for (ConsumerRecord<String, String> r : consumer.poll(Duration.ofMillis(200)).records(tp)) {
            if (out.size() < 10) out.add(r);
        }
    }
    return out;
}

