fun readTen(consumer: KafkaConsumer<String, String>): List<ConsumerRecord<String, String>> {
    val tp = TopicPartition("payments", 0)
    consumer.assign(listOf(tp))
    consumer.seek(tp, 50)
    val out = mutableListOf<ConsumerRecord<String, String>>()
    val deadline = System.nanoTime() + Duration.ofSeconds(5).toNanos()
    while (out.size < 10 && System.nanoTime() < deadline) {
        out += consumer.poll(Duration.ofMillis(200)).records(tp).take(10 - out.size)
    }
    return out
}

