TopicPartition tp = new TopicPartition("payments", 0);
consumer.assign(List.of(tp));
long stopAt = consumer.endOffsets(List.of(tp)).get(tp);

// 3. read until the position reaches the pinned end
while (consumer.position(tp) < stopAt) {
    for (ConsumerRecord<String, String> r : consumer.poll(Duration.ofMillis(500)).records(tp)) {
        if (r.offset() >= stopAt) break;   // arrived after we started
        reconcile(r);
    }
}

