static List<String> replay(Consumer<String, String> consumer, String topic, int partition, long from) {
    TopicPartition tp = new TopicPartition(topic, partition);
    consumer.assign(List.of(tp));
    long stopAt = consumer.endOffsets(List.of(tp)).get(tp);   // pin the end first
    consumer.seek(tp, from);
    List<String> values = new ArrayList<>();
    while (consumer.position(tp) < stopAt) {
        for (ConsumerRecord<String, String> r : consumer.poll(Duration.ofMillis(500)).records(tp)) {
            if (r.offset() < stopAt) values.add(r.value());
        }
    }
    return values;
}

