fun replay(consumer: Consumer<String, String>, topic: String, partition: Int, from: Long): List<String> {
    val tp = TopicPartition(topic, partition)
    consumer.assign(listOf(tp))
    val stopAt = consumer.endOffsets(listOf(tp)).getValue(tp)   // pin the end first
    consumer.seek(tp, from)
    val values = mutableListOf<String>()
    while (consumer.position(tp) < stopAt) {
        consumer.poll(Duration.ofMillis(500)).records(tp)
            .filter { it.offset() < stopAt }
            .mapTo(values) { it.value() }
    }
    return values
}
